import std.io

pub type AppError = Failed(String)

record Cell { hi: Int64 }

fn total(xs: List<Cell>) -> Int64 {
    let s = 0
    for c in xs {
        s = s + c.hi
    }
    return s
}

pub fn main() effect io -> Result<(), AppError> {
    let xs = [Cell { hi: 3 }, Cell { hi: 4 }]
    io.println("${total(xs)}")
    return Ok(())
}
